int ati_remote_wonder_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct usb_host_interface *alt = &interface->cur_altsetting;
    struct ati_remote_dev *dev;
    int rc;

    if (alt->desc.bNumEndpoints < 1)
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    rc = usb_set_interface(udev, alt->desc.bInterfaceNumber, 1);
    if (rc < 0) {
        kfree(dev);
        return rc;
    }

    rc = usb_fill_int_urb(&dev->urb, udev, usb_rcvintpipe(udev, alt->endpoint[0].desc.bEndpointAddress),
                          dev->buffer, ATIRBUF_SIZE, ati_remote_irq, dev,
                          alt->endpoint[0].desc.bInterval);
    if (!dev->urb) {
        kfree(dev);
        return -ENOMEM;
    }

    dev->interface = interface;
    dev->id = id;
    dev->udev = udev;
    usb_make_path(udev, dev->devpath, sizeof(dev->devpath));

    rc = sysfs_create_group(&interface->dev.kobj, &ati_remote_attr_group);
    if (rc) {
        usb_free_urb(dev->urb);
        kfree(dev);
        return rc;
    }

    usb_set_intfdata(interface, dev);
    return 0;
}

int ati_remote_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct ati_remote_dev *dev;
    int i;
    int retval = -ENOMEM;

    iface_desc = interface->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints != 2)
        return -ENODEV;

    dev = kmalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(interface_to_usbdev(interface));
    dev->interface = interface;

    for (i = 0; i < iface_desc->desc.bNumEndpoints; i++) {
        endpoint = &iface_desc->endpoint[i].desc;
        if (!usb_endpoint_is_int_in(endpoint))
            continue;

        dev->bulk_in_endpointAddr = usb_endpoint_num(endpoint);
    }

    if (!dev->bulk_in_endpointAddr) {
        dev_err(&interface->dev, "No interrupt in endpoint found.\n");
        goto error;
    }

    retval = usb_set_interface(dev->udev, 0, 1);
    if (retval < 0) {
        dev_err(&interface->dev, "Failed to set interface 0, altsetting 1: %d\n", retval);
        goto error;
    }

    usb_fill_int_urb(dev->urb, dev->udev,
                     usb_rcvintpipe(dev->udev, dev->bulk_in_endpointAddr),
                     dev->bulk_in_buffer, USB_PKT_SIZE,
                     ati_remote_irq, dev, 100);

    dev->urb->transfer_flags |= URB_CLEANTX;

    dev->input_dev = input_allocate_device();
    if (!dev->input_dev)
        goto error;

    usb_make_path(dev->udev, dev->dev_path, sizeof(dev->dev_path));

    dev->sysfs_group = &dev->sysfs_group;
    dev->sysfs_group.name = "ati_remote";
    dev->sysfs_group.attrs = ati_remote_attrs;
    dev->sysfs_group.num_attrs = ARRAY_SIZE(ati_remote_attrs);

    usb_set_intfdata(interface, dev);

    return 0;

error:
    if (dev) {
        kfree(dev);
    }

    return retval;
}

int ati_remote_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct ati_remote_dev *dev;
    int i;
    int retval = -ENOMEM;

    iface_desc = interface->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints != 2)
        return -ENODEV;

    dev = kmalloc(sizeof(struct ati_remote_dev), GFP_KERNEL);
    if (dev == NULL) {
        goto error;
    }

    dev->udev = usb_get_dev(interface_to_usbdev(interface));
    dev->interface = interface;

    for (i = 0; i < iface_desc->desc.bNumEndpoints; ++i) {
        endpoint = &iface_desc->endpoint[i].desc;
        if (!dev->int_in_endpoint) {
            if ((endpoint->bEndpointAddress & USB_DIR_IN) &&
                ((endpoint->bmAttributes & USB_ENDPOINT_XFERTYPE_MASK) == USB_ENDPOINT_XFER_INT)) {
                dev->int_in_endpoint = endpoint;
            }
        } else if (!dev->bulk_out_endpoint) {
            if (!(endpoint->bEndpointAddress & USB_DIR_IN) &&
                ((endpoint->bmAttributes & USB_ENDPOINT_XFERTYPE_MASK) == USB_ENDPOINT_XFER_BULK)) {
                dev->bulk_out_endpoint = endpoint;
            }
        }
    }

    if (!dev->int_in_endpoint || !dev->bulk_out_endpoint) {
        goto error;
    }

    dev->interrupt = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->interrupt)
        goto error;

    dev->int_buffer = kmalloc(dev->int_in_endpoint->wMaxPacketSize, GFP_KERNEL);
    if (!dev->int_buffer)
        goto error;

    usb_fill_int_urb(dev->interrupt, dev->udev,
                     usb_rcvintpipe(dev->udev, dev->int_in_endpoint->bEndpointAddress),
                     dev->int_buffer, dev->int_in_endpoint->wMaxPacketSize,
                     ati_remote_irq, dev, dev->int_in_endpoint->bInterval);

    dev->interrupt->transfer_flags |= URB_INTERRUPT;

    if (sysfs_create_group(&interface->dev.kobj, &ati_remote_attr_group)) {
        goto error;
    }

    usb_set_intfdata(interface, dev);

    return 0;

error:
    if (dev) {
        if (dev->interrupt)
            usb_free_urb(dev->interrupt);
        kfree(dev->int_buffer);
        kfree(dev);
    }

    return retval;
}

int ati_remote_wonder_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_host_interface *host_iface;
    struct usb_device *udev;
    struct urb *urb;
    int ret;

    if (!interface || !id) {
        return -EINVAL;
    }

    udev = usb_get_dev(interface_to_usbdev(interface));
    host_iface = &interface->altsetting[0];

    if (host_iface->desc.bNumEndpoints < 1) {
        usb_put_dev(udev);
        return -ENODEV;
    }

    urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!urb) {
        usb_put_dev(udev);
        return -ENOMEM;
    }

    if (usb_set_interface(udev, interface->altsetting[0].desc.bInterfaceNumber, 0)) {
        ret = -ENODEV;
        goto free_urb;
    }

    if (usb_make_path(udev, NULL, 0)) {
        ret = -ENODEV;
        goto free_urb;
    }

    ret = sysfs_create_group(&interface->dev.kobj, &ati_remote_wonder_attr_group);
    if (ret) {
        goto free_urb;
    }

    usb_set_intfdata(interface, urb);
    interface->needs_remote_wakeup = 1;

    return 0;

free_urb:
    usb_free_urb(urb);
    usb_put_dev(udev);
    return ret;
}

int ati_remote_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_host_interface *desc;
    struct usb_device *dev;
    struct urb *urb;
    struct ati_remote_dev *device;
    int ret = 0;

    if (interface->cur_altsetting->desc.bInterfaceNumber != 0) {
        dev_err(&interface->dev, "Invalid interface number\n");
        return -ENODEV;
    }

    device = kzalloc(sizeof(*device), GFP_KERNEL);
    if (!device)
        return -ENOMEM;

    dev = usb_get_dev(interface_to_usbdev(interface));
    desc = interface->cur_altsetting;

    if (desc->desc.bNumEndpoints < 1) {
        dev_err(&interface->dev, "No endpoints found\n");
        ret = -ENODEV;
        goto error;
    }

    ret = usb_set_interface(dev, 0, 0);
    if (ret < 0) {
        dev_err(&interface->dev, "Failed to set interface\n");
        goto error;
    }

    urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!urb) {
        ret = -ENOMEM;
        goto error;
    }

    device->dev = dev;
    device->interface = interface;
    device->urb = urb;

    ret = sysfs_create_group(&dev->dev.kobj, &ati_remote_group);
    if (ret < 0) {
        dev_err(&interface->dev, "Failed to create sysfs group\n");
        goto error;
    }

    usb_set_intfdata(interface, device);
    return 0;

error:
    usb_free_urb(urb);
    kfree(device);
    return ret;
}
